shellCommands.command:
rm -rf dist && mkdir -p /tmp/i18n-check && cat > /tmp/i18n-check/check.mjs <<'EOF'
import {I18N} from '/home/sandbox/workspace/node_modules/@gravity-ui/i18n/build/esm/index.js';
const en = {app_title: 'Gravity UI app', current_language: 'Current language: {{language}}'};
const ru = {app_title: 'Приложение на Gravity UI', current_language: 'Текущий язык: {{language}}'};
const i18n = new I18N({lang: 'en', fallbackLang: 'en', data: {en: {app: en}, ru: {app: ru}}});
const t = i18n.keyset('app');
console.log(t('app_title'), '|', t('current_language', {language: 'English'}));
i18n.setLang('ru');
console.log(t('app_title'), '|', t('current_language', {language: 'Русский'}));
EOF
node /tmp/i18n-check/check.mjs; rm -rf /tmp/i18n-check; git status --short

cd /tmp && cat > /tmp/i18n-check.cjs <<'EOF'
const {I18N} = require('/home/sandbox/workspace/node_modules/@gravity-ui/i18n/build/cjs/index.js');
const en = {app_title: 'Gravity UI app', current_language: 'Current language: {{language}}'};
const ru = {app_title: 'Приложение на Gravity UI', current_language: 'Текущий язык: {{language}}'};
const i18n = new I18N({lang: 'en', fallbackLang: 'en', data: {en: {app: en}, ru: {app: ru}}});
const t = i18n.keyset('app');
console.log(t('app_title'), '|', t('current_language', {language: 'English'}));
i18n.setLang('ru');
console.log(t('app_title'), '|', t('current_language', {language: 'Русский'}));
EOF
node /tmp/i18n-check.cjs; rm -f /tmp/i18n-check.cjs; cd /home/sandbox/workspace && git diff package.json && rm -rf dist && git status --short
